    this.email.buildMimeMessage();

    MimeMessage msg = this.email.getMimeMessage();
    msg.saveChanges();

    String[] values = msg.getHeader("X-LongHeader");
    try{ assertEquals(1, values.length);                                                                }catch(Throwable __SHOULD_BE_IGNORED){}

    // the header should be split in two lines
    String[] lines = values[0].split("\\r\\n");
    try{ assertEquals(2, lines.length);                                                                 }catch(Throwable __SHOULD_BE_IGNORED){}

    // there should only be one line-break
    try{ assertTrue(values[0].indexOf("\n") == values[0].lastIndexOf("\n"));                            }catch(Throwable __SHOULD_BE_IGNORED){}
}

